<parameter name="content">import express from 'express';
import bcrypt from 'bcrypt';
import jwt from 'jsonwebtoken';

const app = express();
app.use(express.json());

const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-change-in-production';
const JWT_EXPIRY = '7d';

const users = new Map();
const loginAttempts = new Map();
const sessions = new Map();

const RATE_LIMIT_MAX_ATTEMPTS = 5;
const RATE_LIMIT_WINDOW_MS = 15 * 60 * 1000;
const RATE_LIMIT_LOCKOUT_MS = 30 * 60 * 1000;

function getAttemptKey(email) {
  return `login_${email.toLowerCase()}`;
}

function isLockedOut(email) {
  const key = getAttemptKey(email);
  const record = loginAttempts.get(key);

  if (!record) return false;

  const now = Date.now();
  if (now > record.windowStart + RATE_LIMIT_WINDOW_MS) {
    loginAttempts.delete(key);
    return false;
  }

  if (record.attempts >= RATE_LIMIT_MAX_ATTEMPTS) {
    return now < record.lockedUntil;
  }

  return false;
}

function recordLoginAttempt(email, success) {
  const key = getAttemptKey(email);
  const now = Date.now();
  let record = loginAttempts.get(key);

  if (!record || now > record.windowStart + RATE_LIMIT_WINDOW_MS) {
    record = { attempts: 0, windowStart: now, lockedUntil: 0 };
  }

  if (!success) {
    record.attempts++;
    if (record.attempts >= RATE_LIMIT_MAX_ATTEMPTS) {
      record.lockedUntil = now + RATE_LIMIT_LOCKOUT_MS;
    }
  } else {
    record.attempts = 0;
  }

  loginAttempts.set(key, record);
}

function generateToken(userId) {
  return jwt.sign({ userId }, JWT_SECRET, { expiresIn: JWT_EXPIRY });
}

function validateToken(token) {
  try {
    return jwt.verify(token, JWT_SECRET);
  } catch {
    return null;
  }
}

function authenticateRequest(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing authorization token' });
  }

  const token = authHeader.slice(7);
  const payload = validateToken(token);
  if (!payload) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }

  req.userId = payload.userId;
  next();
}

app.post('/signup', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    if (password.length < 8) {
      return res.status(400).json({ error: 'Password must be at least 8 characters' });
    }

    const normalizedEmail = email.toLowerCase();
    if (users.has(normalizedEmail)) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    const hashedPassword = await bcrypt.hash(password, 12);
    const userId = crypto.randomUUID();

    users.set(normalizedEmail, {
      userId,
      email: normalizedEmail,
      password: hashedPassword,
      createdAt: new Date()
    });

    const token = generateToken(userId);
    res.status(201).json({ token, userId, email: normalizedEmail });
  } catch (error) {
    res.status(500).json({ error: 'Signup failed' });
  }
});

app.post('/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    const normalizedEmail = email.toLowerCase();

    if (isLockedOut(normalizedEmail)) {
      const record = loginAttempts.get(getAttemptKey(normalizedEmail));
      const minutesLeft = Math.ceil((record.lockedUntil - Date.now()) / 60000);
      return res.status(429).json({
        error: `Too many failed attempts. Try again in ${minutesLeft} minutes.`
      });
    }

    const user = users.get(normalizedEmail);

    if (!user) {
      recordLoginAttempt(normalizedEmail, false);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    const passwordMatch = await bcrypt.compare(password, user.password);

    if (!passwordMatch) {
      recordLoginAttempt(normalizedEmail, false);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    recordLoginAttempt(normalizedEmail, true);

    const token = generateToken(user.userId);
    res.json({ token, userId: user.userId, email: user.email });
  } catch (error) {
    res.status(500).json({ error: 'Login failed' });
  }
});

app.get('/profile', authenticateRequest, (req, res) => {
  const user = [...users.values()].find(u => u.userId === req.userId);
  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  res.json({ userId: user.userId, email: user.email, createdAt: user.createdAt });
});

app.post('/logout', authenticateRequest, (req, res) => {
  res.json({ message: 'Logged out successfully' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Auth server running on http://localhost:${PORT}`);
});
