<parameter name="content">import fetch from 'node-fetch';

const BASE_URL = 'http://localhost:3000';

async function request(method, path, body) {
  const options = { method, headers: { 'Content-Type': 'application/json' } };
  if (body) options.body = JSON.stringify(body);
  const res = await fetch(`${BASE_URL}${path}`, options);
  const data = await res.json();
  return { status: res.status, data };
}

async function test() {
  console.log('🧪 Testing Authentication System\n');

  console.log('1️⃣  Signup new user');
  let result = await request('POST', '/signup', { 
    email: 'user@example.com', 
    password: 'MyPassword123' 
  });
  console.log(`   Status: ${result.status}`);
  console.log(`   Token: ${result.data.token?.slice(0, 20)}...`);
  const userToken = result.data.token;

  console.log('\n2️⃣  Try signup with same email (should fail)');
  result = await request('POST', '/signup', { 
    email: 'user@example.com', 
    password: 'DifferentPassword' 
  });
  console.log(`   Status: ${result.status} - ${result.data.error}`);

  console.log('\n3️⃣  Login with correct password');
  result = await request('POST', '/login', { 
    email: 'user@example.com', 
    password: 'MyPassword123' 
  });
  console.log(`   Status: ${result.status}`);
  console.log(`   Token: ${result.data.token?.slice(0, 20)}...`);

  console.log('\n4️⃣  Login with wrong password (5 times for rate limiting)');
  for (let i = 1; i <= 6; i++) {
    result = await request('POST', '/login', { 
      email: 'user@example.com', 
      password: 'WrongPassword' 
    });
    console.log(`   Attempt ${i}: Status ${result.status} - ${result.data.error}`);
  }

  console.log('\n5️⃣  Get profile with token');
  const options = {
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${userToken}`,
      'Content-Type': 'application/json'
    }
  };
  let res = await fetch(`${BASE_URL}/profile`, options);
  let data = await res.json();
  console.log(`   Status: ${res.status}`);
  console.log(`   Profile:`, data);

  console.log('\n6️⃣  Try profile without token (should fail)');
  res = await fetch(`${BASE_URL}/profile`);
  data = await res.json();
  console.log(`   Status: ${res.status} - ${data.error}`);

  console.log('\n✅ Tests complete!');
}

test().catch(console.error);
